local UIModule = CS.Engine.UI.UIModule

---@class LadderStruggleMgr
local LadderStruggleMgr = {}

function LadderStruggleMgr:Init()
    self:CleanProperties()
end

function LadderStruggleMgr:Clear()
    self:CleanProperties()
end

function LadderStruggleMgr:CleanProperties()
    self.struggleRecordData = nil       -- 大乱斗战斗数据
    self.struggleStatistics = nil       -- 大乱斗统计数据
    self.struggleNextSessionIndex = nil -- 大乱斗场次指针
    self.struggleData = nil             -- 大乱斗预处理结果数据
    self.scoreL = nil
    self.scoreR = nil
    self.totalSessionCount = nil        -- 总计的战斗场次（连胜2场或连败2场不需要进行第三场比赛）
    self.isRecordReplay = nil           -- 是否是播放战斗记录
    self.playerInfoList = nil           -- 对战双方的信息
    self.deadLists = nil                -- 角色死亡列表（按死亡时间排序）

    self.systemName = nil
    self.component = nil
end

function LadderStruggleMgr:SetSystem(systemName)
    self.systemName = systemName
    self.component = GameUtils.GetECSComponentBySystemName(systemName)
end

function LadderStruggleMgr:PreprocessingData(struggleRecordData)
    local resultData = {}
    -- 初始数据和战报
    for i, json in ipairs(struggleRecordData) do
        local data
        if type(json) == "table" then
            data = json
        else
            data = table.deserialize(json)
        end
        -- print("[大乱斗] preprocessing for", table.dump(data.recordData[#data.recordData], nil, 5))
        local d = {}
        d.initData = data.initData
        d.recordData = data.recordData
        d.win = data.recordData[#data.recordData].w
        resultData[i] = d
    end

    -- 比分
    local waveNumMax = 3
    local waveNumMin = math.ceil(waveNumMax * 0.5)
    local scoreL = 0
    local scoreR = 0
    local totalSessionCount = #resultData
    for i, waveData in ipairs(resultData) do
        if waveData.win == true then
            scoreL = scoreL + 1
        else
            scoreR = scoreR + 1
        end
        if scoreL >= waveNumMin or scoreR >= waveNumMin then
            totalSessionCount = i
            break
        end
    end

    -- print("[大乱斗] preprocessing score", scoreL, scoreR)

    -- 存活状态
    local deadLists = {}
    for i, waveData in ipairs(resultData) do
        deadLists[i] = {}
        local recordData = waveData.recordData
        self:RecordDeadList(recordData, deadLists[i])
    end
    for i, waveData in ipairs(resultData) do
        waveData.aliveData = {L = {}, R = {}}
        local initData = waveData.initData
        local deadList = deadLists[i]
        for j, roleInfo in ipairs(initData.playerTeam[1]) do
            waveData.aliveData.L[j] = 1 -- 默认存活
            for i, id in ipairs(deadList) do
                if roleInfo.id == id then
                    waveData.aliveData.L[j] = 0
                end
            end
        end
        for j, roleInfo in ipairs(initData.enemyTeam[1]) do
            waveData.aliveData.R[j] = 1 -- 默认存活
            for i, id in pairs(deadList) do
                if roleInfo.id == id then
                    waveData.aliveData.R[j] = 0
                end
            end
        end
    end
    return resultData, scoreL, scoreR, totalSessionCount, deadLists
end

function LadderStruggleMgr:Preprocessing()
    local resultData, scoreL, scoreR, totalSessionCount, deadLists = self:PreprocessingData(self.struggleRecordData)
    self.struggleData = resultData
    self.scoreL = scoreL
    self.scoreR = scoreR
    self.totalSessionCount = totalSessionCount
    self.deadLists = deadLists
end

function LadderStruggleMgr:FightReplay(json)
    FightPreWarMgr:GetInstance():FightReplay(json)
end

--- 设置大乱斗数据
function LadderStruggleMgr:SetLadderStruggleData(data, statistic)
    self.struggleRecordData = data
    self.struggleStatistics = statistic
    self.struggleNextSessionIndex = 1
end

--- 获取下一场大乱斗的数据
function LadderStruggleMgr:GetLadderStruggleNextSessionData()
    local nextData = self.struggleRecordData[self.struggleNextSessionIndex]
    self.struggleNextSessionIndex = self.struggleNextSessionIndex + 1
    return nextData
end

--- 判断大乱斗是否还有下一场
function LadderStruggleMgr:LadderStruggleHasNextSession()
    return self.struggleNextSessionIndex <= self.totalSessionCount
end

--- 判断是否是大乱斗
function LadderStruggleMgr:IsLadderStruggle()
    return not isNull(self.struggleRecordData)
end

--- 判断是否是战斗回放
function LadderStruggleMgr:IsRecordReplay()
    local isRecordReplay = false
    if not isNull(self.isRecordReplay) and self.isRecordReplay == true then
        isRecordReplay = true
    end
    return isRecordReplay
end

function LadderStruggleMgr:RecordDeadList(recordData, deadList)
    -- 深度优先查找
    local copy = recordData
    local queue = {}
    for i = #copy, 1, -1 do
        table.insert(queue, copy[i])
    end
    while #queue > 0 do
        local record = table.remove(queue)
        if record.r == Constants.RecordType.RoleRemove then
            table.insert(deadList, record.id)
        end
        if not isNull(record.subs) then
            for i = #record.subs, 1, -1 do
                table.insert(queue, record.subs[i])
            end
        end
    end
end

--- 获取当前回合的胜负结果
function LadderStruggleMgr:GetCurrentRoundResult()
    local round = self.struggleNextSessionIndex - 1
    local waveData = self.struggleData[round]
    return waveData.win
end

function LadderStruggleMgr:SetPlayerInfoList(data)
    self.playerInfoList = data
end

function LadderStruggleMgr:GetPlayerInfoList()
    return self.playerInfoList
end



--- 大乱斗结算界面
function LadderStruggleMgr:LadderStruggleBattleEnd(args)
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIBattleEndDialog, parameters = 
    { 
        isPassed = args.isWin and 1 or 0,
        showExpAndLevel = false,
        showStruggle = true,
        showTimeCountDown = true,
        countDownCallback = Bind(self, self.BattleEndCallback)
    } })
end

function LadderStruggleMgr:BattleEndCallback()
    local callback = Bind(self, self.NextBattle)
    if LadderStruggleMgr:IsRecordReplay() then
        callback = Bind(self, self.ReturnHome)
    end
    callback()
end

function LadderStruggleMgr:NextBattle()
    local mgr = LadderStruggleMgr
    local hasNext = mgr:LadderStruggleHasNextSession()
    if hasNext then
        --清掉当前所有的ui
        local dialogs = UIModule.CurrentScreen.dialogs
        for i, dialog in pairs(dialogs) do
            UIModule.CloseDialog(dialog)
        end
        BattleEndMgr:ResetCameraAndLight()
        BattleViewMgr:PrepareRestart()

        local json = mgr:GetLadderStruggleNextSessionData()
        mgr:FightReplay(json)
    else
        UIModule.AddUIPage({ id = mgr.component.UIBattleAbstractDialog, parameters = {directShowBattleEnd = true, systemName = mgr.systemName}})
        GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome }, nil, Constants.LoadingType.MainHome) 
    end
end

function LadderStruggleMgr:ReturnHome()
    GameUtils.OpenLoadingPanel({ id = Constants.UITypeIds.UISceneHome }, nil, Constants.LoadingType.MainHome) 
end

return LadderStruggleMgr
